import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  img: { fill: '#e8f5e9', stroke: '#4caf50' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  cls: { fill: '#fff3e0', stroke: '#e65100' },
  pos: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  attn: { fill: '#fce4ec', stroke: '#c62828' },
  ffn: { fill: '#ede7f6', stroke: '#4527a0' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  text: 'var(--text)' as string,
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const BOX_TO_ROW = 90;
const ROW_GAP = 64;
const STEP_GAP = 76;
const WEIGHT_W = 150;
const WEIGHT_H = 80;

interface VitStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void { drawArrow(g as Sel, x, y1, x, y2, { color }); }
function startGroup(g: Gsel, cls: string, step: number): Gsel { return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step)); }

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string, fill: string, stroke: string, width = 760): number {
  const w = width;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', BOX_H).attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w/2 + 24).attr('cy', y + BOX_H/2).attr('r', 14).attr('fill', stroke);
  lbl(g, cx - w/2 + 24, y + BOX_H/2 + 1, String(sn), { size: 12, weight: '700', color: '#fff' });
  lbl(g, cx - w/2 + 48, y + BOX_H/2 - 6, title, { size: 13, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w/2 + 48, y + BOX_H/2 + 10, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function drawShapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 28, 180);
  const h = 28;
  g.append('rect').attr('x', cx - w/2).attr('y', cy - h/2).attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy, text, { size: 8.5, color, font: 'monospace' });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const bw = Math.max(90, text.length * 7.5 + 20);
  const bh = 34;
  g.append('rect').attr('x', cx - bw/2).attr('y', cy - bh/2).attr('width', bw).attr('height', bh).attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function drawSeqMatrix(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = SEQ_W, h = MAT_H): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - h/2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 8, rows: 5, dimTop: 'P', dimRight: 'D' });
}

function drawWeight(g: Gsel, cx: number, cy: number, label: string, sub: string, fill = COLORS.weight.fill, stroke = COLORS.weight.stroke, w = WEIGHT_W, h = WEIGHT_H): void {
  drawMatrixBlock(g as Sel, cx - w/2, cy - h/2, { width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5 });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function drawParamSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160; const h = 34;
  g.append('rect').attr('x', cx - w/2).attr('y', y).attr('width', w).attr('height', h).attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => { lbl(g, cx - w/2 + segW * (i + 0.5), y + h/2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' }); });
  return y + h;
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string, sg: string, c: string, fl: string, cl?: string[]): VitStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex, code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Image grid visualization
// ═══════════════════════════════════════════════════════════════════════════════

function drawImageGrid(g: Gsel, cx: number, cy: number, patchSize: number, gridN: number, color: string): void {
  const totalW = 220;
  const totalH = 220;
  const gg = g.append('g').attr('transform', `translate(${cx - totalW/2}, ${cy - totalH/2})`);
  gg.append('rect').attr('width', totalW).attr('height', totalH).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.4);
  const cellW = totalW / gridN;
  const cellH = totalH / gridN;
  let seed = 42;
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  for (let r = 0; r < gridN; r++) for (let c = 0; c < gridN; c++) {
    const v = 0.15 + lcg() * 0.55;
    gg.append('rect').attr('x', c * cellW + 0.5).attr('y', r * cellH + 0.5).attr('width', cellW - 1).attr('height', cellH - 1).attr('rx', 1).attr('fill', color).attr('opacity', v);
  }
  if (gridN <= 14) {
    for (let i = 1; i < gridN; i++) {
      gg.append('line').attr('x1', i * cellW).attr('y1', 0).attr('x2', i * cellW).attr('y2', totalH).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
      gg.append('line').attr('x1', 0).attr('y1', i * cellH).attr('x2', totalW).attr('y2', i * cellH).attr('stroke', '#fff').attr('stroke-width', 0.3).attr('opacity', 0.5);
    }
  }
  lbl(g, cx - totalW/2 - 8, cy, `${patchSize * gridN}×${patchSize * gridN}`, { size: 8, color: COLORS.muted, anchor: 'end' });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Positional encoding heatmap
// ═══════════════════════════════════════════════════════════════════════════════

function drawPosEncoding(g: Gsel, cx: number, cy: number, nPatches: number, color: string, w = 240, h = 70): void {
  const gg = g.append('g').attr('transform', `translate(${cx - w/2}, ${cy - h/2})`);
  gg.append('rect').attr('width', w).attr('height', h).attr('rx', 4).attr('fill', 'none').attr('stroke', color).attr('stroke-width', 0.8);
  const nCols = Math.min(nPatches + 1, 16);
  const nRows = 5;
  const cw = w / nCols;
  const ch = h / nRows;
  for (let r = 0; r < nRows; r++) for (let c = 0; c < nCols; c++) {
    const v = Math.sin(c * 0.4 + r * 1.2) * 0.4 + 0.5;
    gg.append('rect').attr('x', c * cw).attr('y', r * ch).attr('width', cw - 0.5).attr('height', ch - 0.5).attr('rx', 1).attr('fill', color).attr('opacity', Math.max(0.05, v * 0.6));
  }
  lbl(g, cx - w/2 + 8, cy - h/2 + 10, 'CLS', { size: 7, color: '#fff', anchor: 'start', weight: '600' });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main pipeline
// ═══════════════════════════════════════════════════════════════════════════════

function renderVitPipeline(g: Gsel, startY: number, dModel: number, nPatches: number): { steps: VitStep[]; y: number } {
  const steps: VitStep[] = [];
  let stepId = 1;
  let y = startY;
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));
  const nTokens = nPatches + 1;
  const patchDim = patchSize * patchSize * 3;

  // ── Step 1: Input Image ──────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-img', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Input Image', `image: [3, ${patchSize * gridN}, ${patchSize * gridN}]`, COLORS.img.fill, COLORS.img.stroke);
    arrowDown(gs, CX, y, h, COLORS.img.stroke);
    const imgCY = h + BOX_TO_ROW + 110;
    drawImageGrid(gs, CX, imgCY, patchSize, Math.min(gridN, 14), COLORS.img.stroke);
    lbl(gs, CX, imgCY + 110 + 18, `${patchSize * gridN}×${patchSize * gridN} RGB image`, { size: 9, color: COLORS.muted });
    steps.push(makeStep(stepId, 'Image', 'Input Image', `[3, ${patchSize * gridN}, ${patchSize * gridN}]`, `Input RGB image of size ${patchSize * gridN}×${patchSize * gridN}.`, 'step-img', COLORS.img.stroke, COLORS.img.fill));
    stepId++; y = imgCY + 110 + STEP_GAP;
  }

  // ── Step 2: Patchify ─────────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-patch', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Patchify', `patches = reshape → [${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowDown(gs, CX, y, h, COLORS.patch.stroke);

    // Show small image → arrow → patch strip
    const rowY = h + BOX_TO_ROW + 70;
    const sgW = 120; const sgH = 120;
    const sgG = gs.append('g').attr('transform', `translate(${CX - 260 - sgW/2}, ${rowY - sgH/2})`);
    sgG.append('rect').attr('width', sgW).attr('height', sgH).attr('rx', 4).attr('fill', 'none').attr('stroke', COLORS.img.stroke).attr('stroke-width', 0.8);
    let seed = 99;
    const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
    const gn = Math.min(gridN, 7);
    const cW = sgW / gn; const cH = sgH / gn;
    for (let r = 0; r < gn; r++) for (let c = 0; c < gn; c++) {
      sgG.append('rect').attr('x', c * cW + 0.5).attr('y', r * cH + 0.5).attr('width', cW - 1).attr('height', cH - 1).attr('rx', 1).attr('fill', COLORS.img.stroke).attr('opacity', 0.15 + lcg() * 0.55);
    }
    lbl(gs, CX - 260, rowY - sgH/2 - 12, 'image', { size: 8, color: COLORS.muted });

    // Arrow to patches
    drawArrow(gs as Sel, CX - 260 + sgW/2 + 4, rowY, CX - 80, rowY, { color: COLORS.patch.stroke });
    lbl(gs, CX - 170, rowY - 14, 'split into patches', { size: 8, color: COLORS.muted });

    // Patch strip
    const stripW = 240; const stripH = 56;
    const stripG = gs.append('g').attr('transform', `translate(${CX + 60 - stripW/2}, ${rowY - stripH/2})`);
    stripG.append('rect').attr('width', stripW).attr('height', stripH).attr('rx', 4).attr('fill', 'none').attr('stroke', COLORS.patch.stroke).attr('stroke-width', 1).attr('opacity', 0.4);
    const nShow = Math.min(nPatches, 10);
    const pW = stripW / (nShow + 2);
    for (let i = 0; i < nShow; i++) {
      stripG.append('rect').attr('x', i * pW + 2).attr('y', 4).attr('width', pW - 4).attr('height', stripH - 8).attr('rx', 2).attr('fill', COLORS.patch.stroke).attr('opacity', 0.15 + lcg() * 0.55);
    }
    lbl(gs, CX + 60, rowY - stripH/2 - 12, `${nPatches} patches`, { size: 8.5, color: COLORS.muted });
    lbl(gs, CX + 60, rowY + stripH/2 + 14, `each: ${patchSize}×${patchSize}×3 = ${patchDim}`, { size: 8, color: COLORS.muted });

    // Output matrix
    const outY = rowY + stripH/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, rowY + stripH/2 + 20, outY - MAT_H/2, COLORS.patch.stroke);
    drawSeqMatrix(gs, CX, outY, 'patches', `[${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `reshape: image [3, ${patchSize * gridN}, ${patchSize * gridN}] → patches [${nPatches}, ${patchDim}]`, COLORS.patch.stroke);
    steps.push(makeStep(stepId, 'Patchify', 'Patchify', `reshape → [${nPatches}, ${patchDim}]`, 'Split image into non-overlapping patches and flatten each to a vector.', 'step-patch', COLORS.patch.stroke, COLORS.patch.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 3: Linear Projection ────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-proj', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Linear Projection', `h = patches · W_p + b`, COLORS.patch.fill, COLORS.patch.stroke);
    arrowDown(gs, CX, y, h, COLORS.patch.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    // Input patches
    drawSeqMatrix(gs, CX - 220, rowY, 'patches', `[${nPatches}, ${patchDim}]`, COLORS.patch.fill, COLORS.patch.stroke, 170, MAT_H);
    // Multiply
    opCircle(gs, CX - 40, rowY, '×', COLORS.patch.stroke);
    drawArrow(gs as Sel, CX - 220 + 85 + 4, rowY, CX - 40 - 20, rowY, { color: COLORS.patch.stroke });
    // Weight matrix
    drawWeight(gs, CX + 160, rowY, 'W_p', `[${patchDim}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 150, WEIGHT_H);
    drawArrow(gs as Sel, CX - 40 + 20, rowY, CX + 160 - 75 - 4, rowY, { color: COLORS.patch.stroke });
    // Bias label
    lbl(gs, CX + 160, rowY + WEIGHT_H/2 + 14, '+ b_p', { size: 8, color: COLORS.muted });

    // Output
    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, rowY + MAT_H/2, outY - MAT_H/2, COLORS.patch.stroke);
    drawSeqMatrix(gs, CX, outY, 'x_proj', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `patches [${nPatches}, ${patchDim}] · W_p [${patchDim}, ${dModel}] + b → x_proj [${nPatches}, ${dModel}]`, COLORS.patch.stroke);
    steps.push(makeStep(stepId, 'Project', 'Linear Projection', `patches · W_p + b`, 'Project flattened patches to d_model dimension via learnable linear layer.', 'step-proj', COLORS.patch.stroke, COLORS.patch.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 4: CLS Token Prepend ────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-cls', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Prepend CLS Token', `[CLS] ‖ x_proj → [${nTokens}, ${dModel}]`, COLORS.cls.fill, COLORS.cls.stroke);
    arrowDown(gs, CX, y, h, COLORS.cls.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    // CLS token
    const clsW = 80; const clsH = MAT_H;
    gs.append('rect').attr('x', CX - 260 - clsW/2).attr('y', rowY - clsH/2).attr('width', clsW).attr('height', clsH).attr('rx', 6).attr('fill', COLORS.cls.fill).attr('stroke', COLORS.cls.stroke).attr('stroke-width', 1.5);
    lbl(gs, CX - 260, rowY - 6, 'CLS', { size: 10, weight: '700', color: COLORS.cls.stroke });
    lbl(gs, CX - 260, rowY + 10, `[${dModel}]`, { size: 8, color: COLORS.muted, font: 'monospace' });

    // Concat symbol
    lbl(gs, CX - 150, rowY, '‖', { size: 18, weight: '700', color: COLORS.cls.stroke });
    drawArrow(gs as Sel, CX - 260 + clsW/2 + 4, rowY, CX - 165, rowY, { color: COLORS.cls.stroke });

    // Patches
    drawSeqMatrix(gs, CX + 60, rowY, 'x_proj', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke, 180, MAT_H);
    drawArrow(gs as Sel, CX - 135, rowY, CX + 60 - 90 - 4, rowY, { color: COLORS.cls.stroke });

    // Output
    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, rowY + MAT_H/2, outY - MAT_H/2, COLORS.cls.stroke);
    drawSeqMatrix(gs, CX, outY, 'tokens', `[${nTokens}, ${dModel}]`, COLORS.cls.fill, COLORS.cls.stroke, 220, MAT_H);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `[CLS] [1, ${dModel}] ‖ x_proj [${nPatches}, ${dModel}] → tokens [${nTokens}, ${dModel}]`, COLORS.cls.stroke);
    steps.push(makeStep(stepId, 'CLS', 'Prepend CLS Token', `[CLS] ‖ x_proj`, 'Learned CLS token prepended for classification. Its final representation aggregates global info.', 'step-cls', COLORS.cls.stroke, COLORS.cls.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 5: Position Embeddings ──────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-pos', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Add Position Embeddings', `x = tokens + PE`, COLORS.pos.fill, COLORS.pos.stroke);
    arrowDown(gs, CX, y, h, COLORS.pos.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX - 220, rowY, 'tokens', `[${nTokens}, ${dModel}]`, COLORS.cls.fill, COLORS.cls.stroke, 180, MAT_H);
    opCircle(gs, CX - 40, rowY, '+', COLORS.pos.stroke);
    drawArrow(gs as Sel, CX - 220 + 90 + 4, rowY, CX - 40 - 20, rowY, { color: COLORS.pos.stroke });

    const peW = 200; const peH = 70;
    drawPosEncoding(gs, CX + 160, rowY, nPatches, COLORS.pos.stroke, peW, peH);
    lbl(gs, CX + 160, rowY - peH/2 - 12, 'learned PE', { size: 8, color: COLORS.muted });
    drawArrow(gs as Sel, CX + 160 - peW/2 - 4, rowY, CX - 40 + 20, rowY, { color: COLORS.pos.stroke });

    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX - 40, rowY + MAT_H/2, outY - MAT_H/2, COLORS.pos.stroke);
    drawSeqMatrix(gs, CX, outY, 'x_embed', `[${nTokens}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `tokens [${nTokens}, ${dModel}] + PE [${nTokens}, ${dModel}] → x_embed [${nTokens}, ${dModel}]`, COLORS.pos.stroke);
    steps.push(makeStep(stepId, 'PosEnc', 'Add Position Embeddings', `x = tokens + PE`, 'Learned positional embeddings encode spatial location of each patch.', 'step-pos', COLORS.pos.stroke, COLORS.pos.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 6: LayerNorm ────────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-norm', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Layer Normalization', `x_norm = LN(x_embed)`, COLORS.norm.fill, COLORS.norm.stroke);
    arrowDown(gs, CX, y, h, COLORS.norm.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX - 200, rowY, 'x_embed', `[${nTokens}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke, 180, MAT_H);
    drawBadge(gs, CX + 30, rowY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    drawArrow(gs as Sel, CX - 200 + 90 + 4, rowY, CX + 30 - 55, rowY, { color: COLORS.norm.stroke });
    lbl(gs, CX + 30 + 70, rowY, 'γ, β', { size: 8, color: COLORS.muted, anchor: 'start' });

    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX + 30, rowY + 17, outY - MAT_H/2, COLORS.norm.stroke);
    drawSeqMatrix(gs, CX, outY, 'x_norm', `[${nTokens}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `LayerNorm(x_embed) → x_norm [${nTokens}, ${dModel}]`, COLORS.norm.stroke);
    steps.push(makeStep(stepId, 'Norm', 'Layer Normalization', `x_norm = LN(x)`, 'Normalize features per-token before attention.', 'step-norm', COLORS.norm.stroke, COLORS.norm.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 7: Self-Attention ───────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-attn', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Multi-Head Self-Attention', `attn = softmax(Q·K^T/√d_k)·V`, COLORS.attn.fill, COLORS.attn.stroke);
    arrowDown(gs, CX, y, h, COLORS.attn.stroke);

    // Input
    const inY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX, inY, 'x_norm', `[${nTokens}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke);

    // QKV projection row
    const qkvY = inY + MAT_H/2 + ROW_GAP + 30;
    const qkvGap = 190;
    const qX = CX - qkvGap;
    const kX = CX;
    const vX = CX + qkvGap;

    lbl(gs, qX, qkvY - 50, 'Q projection', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, kX, qkvY - 50, 'K projection', { size: 9, weight: '600', color: COLORS.attn.stroke });
    lbl(gs, vX, qkvY - 50, 'V projection', { size: 9, weight: '600', color: COLORS.attn.stroke });

    drawWeight(gs, qX, qkvY, 'W_q', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 130, 64);
    drawWeight(gs, kX, qkvY, 'W_k', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 130, 64);
    drawWeight(gs, vX, qkvY, 'W_v', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 130, 64);

    // Arrows from input to QKV
    drawArrow(gs as Sel, CX, inY + MAT_H/2, qX, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, CX, inY + MAT_H/2, kX, qkvY - 32 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, CX, inY + MAT_H/2, vX, qkvY - 32 - 4, { color: COLORS.attn.stroke });

    // Score row
    const scoreY = qkvY + 32 + ROW_GAP;
    const scoreBoxW = 200; const scoreBoxH = 38;
    gs.append('rect').attr('x', CX - 140 - scoreBoxW/2).attr('y', scoreY - scoreBoxH/2).attr('width', scoreBoxW).attr('height', scoreBoxH).attr('rx', 6).attr('fill', '#fff').attr('stroke', COLORS.attn.stroke).attr('stroke-width', 1);
    lbl(gs, CX - 140, scoreY, `Q @ K^T / √d_k`, { size: 9.5, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });

    drawBadge(gs, CX + 140, scoreY, 'Softmax', COLORS.attn.fill, COLORS.attn.stroke);
    drawArrow(gs as Sel, CX - 140 + scoreBoxW/2 + 4, scoreY, CX + 140 - 50, scoreY, { color: COLORS.attn.stroke });

    // Arrows from QK to score
    drawArrow(gs as Sel, qX, qkvY + 32, CX - 140 - 30, scoreY - scoreBoxH/2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, kX, qkvY + 32, CX - 140 + 30, scoreY - scoreBoxH/2 - 4, { color: COLORS.attn.stroke });
    drawArrow(gs as Sel, vX, qkvY + 32, CX + 140, scoreY + scoreBoxH/2 + 4, { color: COLORS.attn.stroke });

    // Attention weights heatmap
    const awY = scoreY + scoreBoxH/2 + ROW_GAP + 30;
    const awW = 140; const awH = 60;
    const awG = gs.append('g').attr('transform', `translate(${CX - awW/2}, ${awY - awH/2})`);
    awG.append('rect').attr('width', awW).attr('height', awH).attr('rx', 4).attr('fill', 'none').attr('stroke', COLORS.attn.stroke).attr('stroke-width', 0.8);
    const awCols = Math.min(nTokens, 14);
    const awRows = Math.min(nTokens, 8);
    const acW = awW / awCols; const acH = awH / awRows;
    for (let r = 0; r < awRows; r++) for (let c = 0; c < awCols; c++) {
      const v = Math.exp(-Math.abs(r - c) * 0.5) * 0.6 + 0.1;
      awG.append('rect').attr('x', c * acW).attr('y', r * acH).attr('width', acW - 0.5).attr('height', acH - 0.5).attr('rx', 1).attr('fill', COLORS.attn.stroke).attr('opacity', v);
    }
    lbl(gs, CX, awY - awH/2 - 12, `attention weights [${nTokens}, ${nTokens}]`, { size: 8.5, color: COLORS.muted });
    arrowDown(gs, CX + 140, scoreY + scoreBoxH/2 + 4, awY - awH/2 - 4, COLORS.attn.stroke);

    // × V multiply and output projection
    const outRowY = awY + awH/2 + ROW_GAP;
    opCircle(gs, CX - 80, outRowY, '×', COLORS.attn.stroke);
    lbl(gs, CX - 80, outRowY - 26, 'attn · V', { size: 8, color: COLORS.muted });
    arrowDown(gs, CX - 80, awY + awH/2 + 4, outRowY - 20, COLORS.attn.stroke);
    lbl(gs, CX - 80 + 46, outRowY - 4, 'V', { size: 9, weight: '600', color: COLORS.attn.stroke, anchor: 'start' });
    drawWeight(gs, CX + 100, outRowY, 'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 120, 60);
    drawArrow(gs as Sel, CX - 80 + 20, outRowY, CX + 100 - 60 - 4, outRowY, { color: COLORS.attn.stroke });
    lbl(gs, CX + 100 + 80, outRowY, '→ attn_out', { size: 9, color: COLORS.attn.stroke, anchor: 'start' });

    // Output matrix
    const attnOutY = outRowY + 30 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX + 100, outRowY + 30, attnOutY - MAT_H/2, COLORS.attn.stroke);
    drawSeqMatrix(gs, CX, attnOutY, 'attn_out', `[${nTokens}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
    drawShapeEq(gs, CX, attnOutY + MAT_H/2 + 24, `softmax(Q·K^T/√d_k) · V · W_o → attn_out [${nTokens}, ${dModel}]`, COLORS.attn.stroke);
    steps.push(makeStep(stepId, 'Attn', 'Multi-Head Self-Attention', `softmax(Q·K^T/√d_k)·V`, 'Multi-head self-attention with Q/K/V projections, scaled dot-product, and output projection.', 'step-attn', COLORS.attn.stroke, COLORS.attn.fill));
    stepId++; y = attnOutY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 8: Residual Add 1 ───────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-res1', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Residual Connection 1', `h = x_embed + attn_out`, COLORS.img.fill, COLORS.img.stroke);
    arrowDown(gs, CX, y, h, COLORS.img.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX - 220, rowY, 'x_embed', `[${nTokens}, ${dModel}]`, COLORS.pos.fill, COLORS.pos.stroke, 170, MAT_H);
    opCircle(gs, CX, rowY, '⊕', COLORS.img.stroke);
    drawArrow(gs as Sel, CX - 220 + 85 + 4, rowY, CX - 20, rowY, { color: COLORS.img.stroke });
    drawSeqMatrix(gs, CX + 220, rowY, 'attn_out', `[${nTokens}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 220 - 85 - 4, rowY, CX + 20, rowY, { color: COLORS.img.stroke });

    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, rowY + 20, outY - MAT_H/2, COLORS.img.stroke);
    drawSeqMatrix(gs, CX, outY, 'h_attn', `[${nTokens}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `x_embed + attn_out → h_attn [${nTokens}, ${dModel}]`, COLORS.img.stroke);
    steps.push(makeStep(stepId, 'Res1', 'Residual Connection 1', `x + attn`, 'Add residual connection to preserve gradient flow through attention.', 'step-res1', COLORS.img.stroke, COLORS.img.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 9: FFN ──────────────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-ffn', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Feed-Forward Network', `ffn = W_down(GELU(W_up(LN(h))))`, COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowDown(gs, CX, y, h, COLORS.ffn.stroke);

    // Input
    const inY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX, inY, 'h_attn', `[${nTokens}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke);

    // LayerNorm
    const normY = inY + MAT_H/2 + ROW_GAP;
    drawBadge(gs, CX, normY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    arrowDown(gs, CX, inY + MAT_H/2, normY - 17, COLORS.ffn.stroke);

    // W_up
    const dFf = 4 * dModel;
    const wUpY = normY + 17 + ROW_GAP + WEIGHT_H/2;
    drawWeight(gs, CX, wUpY, 'W_up', `[${dModel}, ${dFf}]`, COLORS.weight.fill, COLORS.weight.stroke, 150, WEIGHT_H);
    arrowDown(gs, CX, normY + 17, wUpY - WEIGHT_H/2, COLORS.ffn.stroke);
    lbl(gs, CX + 100, wUpY - 10, 'up-project', { size: 8, color: COLORS.muted, anchor: 'start' });

    // GELU
    const geluGap = Math.round(ROW_GAP * 0.75);
    const geluY = wUpY + WEIGHT_H/2 + geluGap;
    drawBadge(gs, CX, geluY, 'GELU', COLORS.ffn.fill, COLORS.ffn.stroke);
    arrowDown(gs, CX, wUpY + WEIGHT_H/2, geluY - 17, COLORS.ffn.stroke);

    // W_down
    const wDownY = geluY + 17 + geluGap + WEIGHT_H/2;
    drawWeight(gs, CX, wDownY, 'W_down', `[${dFf}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, 150, WEIGHT_H);
    arrowDown(gs, CX, geluY + 17, wDownY - WEIGHT_H/2, COLORS.ffn.stroke);
    lbl(gs, CX + 100, wDownY - 10, 'down-project', { size: 8, color: COLORS.muted, anchor: 'start' });

    // Output
    const ffnOutY = wDownY + WEIGHT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, wDownY + WEIGHT_H/2, ffnOutY - MAT_H/2, COLORS.ffn.stroke);
    drawSeqMatrix(gs, CX, ffnOutY, 'ffn_out', `[${nTokens}, ${dModel}]`, COLORS.ffn.fill, COLORS.ffn.stroke);
    drawShapeEq(gs, CX, ffnOutY + MAT_H/2 + 24, `W_down(GELU(W_up(LN(h_attn)))) → ffn_out [${nTokens}, ${dModel}]`, COLORS.ffn.stroke);
    steps.push(makeStep(stepId, 'FFN', 'Feed-Forward Network', `W_down(GELU(W_up(LN(h))))`, 'Two linear layers with GELU activation, expanding to 4×d_model then projecting back.', 'step-ffn', COLORS.ffn.stroke, COLORS.ffn.fill));
    stepId++; y = ffnOutY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 10: Residual Add 2 ──────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-res2', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Residual Connection 2', `h = h_attn + ffn_out`, COLORS.img.fill, COLORS.img.stroke);
    arrowDown(gs, CX, y, h, COLORS.img.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX - 220, rowY, 'h_attn', `[${nTokens}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 170, MAT_H);
    opCircle(gs, CX, rowY, '⊕', COLORS.img.stroke);
    drawArrow(gs as Sel, CX - 220 + 85 + 4, rowY, CX - 20, rowY, { color: COLORS.img.stroke });
    drawSeqMatrix(gs, CX + 220, rowY, 'ffn_out', `[${nTokens}, ${dModel}]`, COLORS.ffn.fill, COLORS.ffn.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 220 - 85 - 4, rowY, CX + 20, rowY, { color: COLORS.img.stroke });

    const outY = rowY + MAT_H/2 + ROW_GAP + MAT_H/2;
    arrowDown(gs, CX, rowY + 20, outY - MAT_H/2, COLORS.img.stroke);
    drawSeqMatrix(gs, CX, outY, 'h_enc', `[${nTokens}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke);
    drawShapeEq(gs, CX, outY + MAT_H/2 + 24, `h_attn + ffn_out → h_enc [${nTokens}, ${dModel}]   (×L layers)`, COLORS.img.stroke);
    steps.push(makeStep(stepId, 'Res2', 'Residual Connection 2', `h + ffn`, 'Add residual connection after FFN. This completes one transformer layer (×L total).', 'step-res2', COLORS.img.stroke, COLORS.img.fill));
    stepId++; y = outY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 11: Extract CLS ─────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-clsout', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Extract CLS Output', `cls_out = h_enc[0]`, COLORS.out.fill, COLORS.out.stroke);
    arrowDown(gs, CX, y, h, COLORS.out.stroke);

    const rowY = h + BOX_TO_ROW + MAT_H/2;
    drawSeqMatrix(gs, CX - 200, rowY, 'h_enc', `[${nTokens}, ${dModel}]`, COLORS.img.fill, COLORS.img.stroke, 200, MAT_H);

    const clsOutX = CX + 180;
    const clsOutW = 110; const clsOutH = 54;
    gs.append('rect').attr('x', clsOutX - clsOutW/2).attr('y', rowY - clsOutH/2).attr('width', clsOutW).attr('height', clsOutH).attr('rx', 6).attr('fill', COLORS.cls.fill).attr('stroke', COLORS.out.stroke).attr('stroke-width', 1.5);
    lbl(gs, clsOutX, rowY - 6, 'CLS', { size: 11, weight: '700', color: COLORS.out.stroke });
    lbl(gs, clsOutX, rowY + 12, `[${dModel}]`, { size: 8, color: COLORS.muted, font: 'monospace' });
    drawArrow(gs as Sel, CX - 200 + 100 + 4, rowY - MAT_H/2 + 10, clsOutX - clsOutW/2 - 4, rowY, { color: COLORS.out.stroke });
    lbl(gs, CX + 20, rowY - MAT_H/2 + 4, 'h[0]', { size: 8.5, color: COLORS.muted });

    drawShapeEq(gs, CX, rowY + MAT_H/2 + 24, `h_enc [${nTokens}, ${dModel}] → cls_out = h_enc[0, :] → [${dModel}]`, COLORS.out.stroke);
    steps.push(makeStep(stepId, 'CLS Out', 'Extract CLS Output', `cls_out = h_enc[0]`, 'CLS token aggregates global image information for classification.', 'step-clsout', COLORS.out.stroke, COLORS.out.fill));
    stepId++; y = rowY + MAT_H/2 + 24 + STEP_GAP;
  }

  // ── Step 12: Output ──────────────────────────────────────────────────────
  {
    const gs = startGroup(g, 'step-out', stepId);
    const h = stepHeader(gs, CX, y, stepId, 'Output', `cls_features: [${dModel}]`, COLORS.out.fill, COLORS.out.stroke);
    arrowDown(gs, CX, y, h, COLORS.out.stroke);
    const finalY = h + BOX_TO_ROW + 20;
    const vecW = 400; const vecH = 44;
    const vecG = gs.append('g').attr('transform', `translate(${CX - vecW/2}, ${finalY})`);
    vecG.append('rect').attr('width', vecW).attr('height', vecH).attr('rx', 6).attr('fill', COLORS.out.fill).attr('stroke', COLORS.out.stroke).attr('stroke-width', 1.5);
    const nBlocks = 32;
    const bW = vecW / nBlocks;
    for (let i = 0; i < nBlocks; i++) {
      const v = 0.1 + Math.abs(Math.sin(i * 0.6)) * 0.5;
      vecG.append('rect').attr('x', i * bW + 1).attr('y', 4).attr('width', bW - 2).attr('height', vecH - 8).attr('rx', 2).attr('fill', COLORS.out.stroke).attr('opacity', v);
    }
    lbl(gs, CX, finalY + vecH + 18, `CLS feature vector [${dModel}]`, { size: 9.5, color: COLORS.muted });
    steps.push(makeStep(stepId, 'Output', 'CLS Features', `[${dModel}]`, 'Final CLS token features for downstream classification head.', 'step-out', COLORS.out.stroke, COLORS.out.fill));
    y = finalY + vecH + 48;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderVitEncoderDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 768;
  const nPatches = Number(params.n_patches) || 196;

  const root = g as unknown as Gsel;
  let y = 28;

  lbl(root, CX, y, 'ViT Encoder', { size: 18, weight: '700', color: COLORS.text });
  y += 24;
  const patchSize = 16;
  const gridN = Math.round(Math.sqrt(nPatches));
  lbl(root, CX, y, `Vision Transformer · d_model=${dModel} · ${gridN}×${gridN} patches (${patchSize}×${patchSize})`, { size: 11, color: COLORS.muted });
  y += 32;

  const patchDim = patchSize * patchSize * 3;
  const patchEmbedParams = patchDim * dModel + dModel;
  const posParams = (nPatches + 1) * dModel;
  const clsParams = dModel;
  y = drawParamSummary(root, CX, y, [`d_model=${dModel}`, `patches=${nPatches}`, `embed≈${fmtNum(patchEmbedParams + posParams + clsParams)}`]);
  y += 20;

  const result = renderVitPipeline(root, y, dModel, nPatches);

  let footerY = result.y + 24;

  const nTokens = nPatches + 1;
  const dFf = 4 * dModel;
  const attnParams = dModel * dModel * 4;
  const ffnParams = dModel * dFf * 2;
  const normParams = dModel * 2 * 2;
  const totalPerLayer = attnParams + ffnParams + normParams;

  const insightText = `ViT splits a ${patchSize * gridN}×${patchSize * gridN} image into ${nPatches} non-overlapping ${patchSize}×${patchSize} patches, linearly embeds each to d_model=${dModel}, prepends a learnable CLS token, adds positional embeddings, then processes through L transformer layers. The CLS token output aggregates global image info for classification.`;
  const perfText = `Patch embed: ${fmtNum(patchEmbedParams)} params. Per-layer attention (Q/K/V/O): ${fmtNum(attnParams)}. Per-layer FFN: ${fmtNum(ffnParams)}. Norms: ${fmtNum(normParams)}. Total per layer: ~${fmtNum(totalPerLayer)} params.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 14;

  const codeLines = [
    '# Vision Transformer Encoder',
    `patches = rearrange(image, 'b c (h p1) (w p2) -> b (h w) (p1 p2 c)', p1=${patchSize}, p2=${patchSize})`,
    `x_proj = patches @ W_patch + b_patch         # [B, ${nPatches}, ${dModel}]`,
    `cls_token = learnable parameter               # [1, ${dModel}]`,
    `tokens = torch.cat([cls_token, x_proj], dim=1) # [B, ${nTokens}, ${dModel}]`,
    `x = tokens + positional_embedding              # learned PE`,
    'for layer in transformer_layers:',
    '    x = x + MultiHeadAttention(LayerNorm(x))',
    '    x = x + FFN(LayerNorm(x))',
    `cls_output = x[:, 0, :]                        # [B, ${dModel}]`,
  ];

  footerY = drawCodeAnnotation(g, 80, footerY, W - 160, 'ViT Encoder — Vision Transformer', [], codeLines);

  return { width: W, height: footerY + 24, steps: result.steps };
}
